    // calculate_cache_metrics: 캐시 메트릭 계산
    func calculate_cache_metrics(
        l1_loads: u64,
        l1_misses: u64,
        l2_loads: u64,
        l2_misses: u64,
        l3_loads: u64,
        l3_misses: u64
    ) -> CacheMetrics {
        let l1_miss_rate = if l1_loads > 0 { f32(l1_misses) / f32(l1_loads) * 100.0 } else { 0.0 };
        let l2_miss_rate = if l2_loads > 0 { f32(l2_misses) / f32(l2_loads) * 100.0 } else { 0.0 };
        let l3_miss_rate = if l3_loads > 0 { f32(l3_misses) / f32(l3_loads) * 100.0 } else { 0.0 };

        return CacheMetrics {
            l1_loads: l1_loads,
            l1_misses: l1_misses,
            l1_miss_rate: l1_miss_rate,
            l2_loads: l2_loads,
            l2_misses: l2_misses,
            l2_miss_rate: l2_miss_rate,
            l3_loads: l3_loads,
            l3_misses: l3_misses,
            l3_miss_rate: l3_miss_rate,
        };
    }

    // ========================================================================
    // 정체 분석
    // ========================================================================

    // analyze_stalls: 정체 원인 분석
    func analyze_stalls(
        total_cycles: u64,
        resource_stalls: u64,
        l1_dcache_misses: u64,
        llc_misses: u64,
        branch_misses: u64,
        instructions: u64
    ) -> StallAnalysis {
        // 정체 사이클 분해
        let backend_stalls = resource_stalls;
        let memory_stalls = u64(f32(llc_misses) * 100.0);  // 메모리 대기: ~100 사이클/미스
        let branch_stalls = u64(f32(branch_misses) * 15.0);  // 분기 미스: ~15 사이클/미스
        let frontend_stalls = if total_cycles > resource_stalls { total_cycles - resource_stalls - memory_stalls - branch_stalls } else { 0 };

        return StallAnalysis {
            frontend_stalls: frontend_stalls,
            backend_stalls: backend_stalls,
            resource_stalls: resource_stalls,
            memory_stalls: memory_stalls,
            branch_stalls: branch_stalls,
        };
    }

