        print(\"\");
        let aos_total_stalls = aos_stalls.frontend_stalls + aos_stalls.backend_stalls + aos_stalls.memory_stalls + aos_stalls.branch_stalls;
        let aos_frontend_pct = u32(f32(aos_stalls.frontend_stalls) / f32(aos_total_stalls) * 100.0);
        let aos_backend_pct = u32(f32(aos_stalls.backend_stalls) / f32(aos_total_stalls) * 100.0);
        let aos_memory_pct = u32(f32(aos_stalls.memory_stalls) / f32(aos_total_stalls) * 100.0);
