//     L1-dcache-loads,L1-dcache-load-misses,LLC-loads,LLC-load-misses,\
//     dTLB-loads,dTLB-load-misses,branch-instructions,branch-misses,\
//     resource-stalls <program>
//
// ============================================================================

module perf_analyzer {
    // ========================================================================
    // 데이터 구조
    // ========================================================================

    // PerformanceCounter: 단일 성능 카운터
    struct PerformanceCounter {
        event_name: string;
        value: u64;
        unit: string;
        description: string;
    }

    // CacheMetrics: 캐시 계층 메트릭
    struct CacheMetrics {
        l1_loads: u64;
        l1_misses: u64;
        l1_miss_rate: f32;
        l2_loads: u64;
        l2_misses: u64;
        l2_miss_rate: f32;
        l3_loads: u64;
        l3_misses: u64;
        l3_miss_rate: f32;
    }

    // MemoryHierarchy: 메모리 계층 분석
    struct MemoryHierarchy {
        l1_dcache: CacheMetrics;
        l2_cache: CacheMetrics;
        l3_cache: CacheMetrics;
        tlb: CacheMetrics;
        memory_bandwidth_gb_s: f32;
    }

    // StallAnalysis: 정체(Stall) 분석
    struct StallAnalysis {
        frontend_stalls: u64;      // 명령어 페칭 지연
        backend_stalls: u64;       // 실행 리소스 부족
        resource_stalls: u64;      // 리소스 경합
        memory_stalls: u64;        // 메모리 대기
        branch_stalls: u64;        // 분기 예측 미스
    }

    // DetailedReport: 상세 리포트
    struct DetailedReport {
        total_cycles: u64;
        total_instructions: u64;
        counters: [PerformanceCounter];
        cache_metrics: MemoryHierarchy;
        stall_analysis: StallAnalysis;
    }

