    // analyze_stalls: 정체 원인 분석
    func analyze_stalls(
        total_cycles: u64,
        resource_stalls: u64,
        l1_dcache_misses: u64,
        llc_misses: u64,
        branch_misses: u64,
        instructions: u64
    ) -> StallAnalysis {
        // 정체 사이클 분해
        let backend_stalls = resource_stalls;
        let memory_stalls = u64(f32(llc_misses) * 100.0);  // 메모리 대기: ~100 사이클/미스
        let branch_stalls = u64(f32(branch_misses) * 15.0);  // 분기 미스: ~15 사이클/미스
        let frontend_stalls = if total_cycles > resource_stalls { total_cycles - resource_stalls - memory_stalls - branch_stalls } else { 0 };

        return StallAnalysis {
            frontend_stalls: frontend_stalls,
            backend_stalls: backend_stalls,
            resource_stalls: resource_stalls,
            memory_stalls: memory_stalls,
            branch_stalls: branch_stalls,
        };
    }

