    // generate_stall_breakdown_graph: 정체 분해 그래프
    func generate_stall_breakdown_graph(
        soa_stalls: StallAnalysis,
        aos_stalls: StallAnalysis,
        soa_cycles: u64,
        aos_cycles: u64
    ) {
        print(\"╔════════════════════════════════════════════════════════════════╗\");
        print(\"║ Stall Cycle Breakdown: Resource Contention Analysis           ║\");
        print(\"╚════════════════════════════════════════════════════════════════╝\");
        print(\"\");

        print(\"📊 SoA Stall Distribution\");
        print(\"\");
        let soa_total_stalls = soa_stalls.frontend_stalls + soa_stalls.backend_stalls + soa_stalls.memory_stalls + soa_stalls.branch_stalls;
        let soa_frontend_pct = u32(f32(soa_stalls.frontend_stalls) / f32(soa_total_stalls) * 100.0);
        let soa_backend_pct = u32(f32(soa_stalls.backend_stalls) / f32(soa_total_stalls) * 100.0);
        let soa_memory_pct = u32(f32(soa_stalls.memory_stalls) / f32(soa_total_stalls) * 100.0);
        let soa_branch_pct = u32(f32(soa_stalls.branch_stalls) / f32(soa_total_stalls) * 100.0);

        print(\"  Frontend Stalls: \" + soa_frontend_pct + \"% (\" + soa_stalls.frontend_stalls + \" cycles)\");
        for i = 0; i < soa_frontend_pct / 5; i = i + 1 {
