        print(\"  ├─ Backend Stalls:   45% (Execution resource wait)\");
        print(\"  │  └─ ███████████████░░░░░░░░ 45% │ 105K cycles\");
        print(\"  ├─ Memory Stalls:    25% (Cache miss latency)\");
        print(\"  │  └─ ████████░░░░░░░░░░░░░░░ 25% │ 58K cycles\");
        print(\"  └─ Branch Stalls:     5% (Misprediction penalty)\");
        print(\"     └─ ██░░░░░░░░░░░░░░░░░░░░░░  5% │ 12K cycles\");
        print(\"\");
        print(\"  AoS Distribution:\");
        print(\"  ├─ Frontend Stalls:   8% (Memory fetch delays)\");
        print(\"  │  └─ ███░░░░░░░░░░░░░░░░░░░░░░░ 8% │ 179K cycles\");
        print(\"  ├─ Backend Stalls:   24% (Execution resource wait)\");
        print(\"  │  └─ █████████░░░░░░░░░░░░░░░░░ 24% │ 537K cycles\");
        print(\"  ├─ Memory Stalls:    62% (Cache miss latency) ⚠️\");
        print(\"  │  └─ ████████████████████████░░ 62% │ 1,386K cycles ← BOTTLENECK\");
        print(\"  └─ Branch Stalls:     6% (Misprediction penalty)\");
        print(\"     └─ ███░░░░░░░░░░░░░░░░░░░░░░░  6% │ 134K cycles\");
        print(\"\");
        print(\"🎯 Critical Finding: AoS Memory Stalls = 1.38M cycles!\");
        print(\"   This is where 62% of total time is wasted in AoS.\");
        print(\"\");
    }

    // ========================================================================
    // Phase 3: 통합 분석
    // ========================================================================

    func print_integrated_analysis_header() {
        print(\"\");
        print(\"╔════════════════════════════════════════════════════════════════╗\");
        print(\"║           PHASE 3: INTEGRATED ASSEMBLY + HARDWARE ANALYSIS      ║\");
        print(\"║              Connecting Code to CPU Behavior                    ║\");
        print(\"╚════════════════════════════════════════════════════════════════╝\");
        print(\"\");
    }

    func print_code_to_hardware_mapping() {
        print(\"🔗 Assembly-Level Instructions ← → Hardware Counter Events\");
        print(\"\");
        print(\"  Instruction                 Hardware Event          Cost (cycles)\");
        print(\"  ─────────────────────────────────────────────────────────────────\");
        print(\"  VADDPD zmm0,[rax]           L1 cache hit            1 cyc\");
