        print(\"\");
        print(\"  [Continued for 156 SIMD instructions...]\");
        print(\"\");
    }

    func print_asm_register_density() {
        print(\"📊 AVX-512 Register Utilization Density\");
        print(\"\");
        print(\"  ┌─────────────┬──────────┬──────────┬──────────┐\");
